import React, { useState, useRef } from 'react';
import { Territory } from './types';

interface GameMapProps {
    territories: Territory[];
    getCountryColor: (ownerId: string) => string;
    onTerritoryClick: (territory: Territory) => void;
}

export const GameMap: React.FC<GameMapProps> = ({ territories, getCountryColor, onTerritoryClick }) => {
    const [transform, setTransform] = useState({ x: 0, y: 0, k: 1 });
    const [isDragging, setIsDragging] = useState(false);
    const lastMousePosition = useRef({ x: 0, y: 0 });
    const dragStart = useRef({ x: 0, y: 0 });
    const svgRef = useRef<SVGSVGElement>(null);
    
    // Touch handling refs
    const lastTouchDistance = useRef<number | null>(null);
    const lastTouchCenter = useRef<{ x: number, y: number } | null>(null);

    const handleWheel = (e: React.WheelEvent) => {
        const scaleAmount = -e.deltaY * 0.001;
        const newScale = Math.min(Math.max(0.5, transform.k + scaleAmount), 10);
        
        setTransform(prev => ({ ...prev, k: newScale }));
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        setIsDragging(true);
        lastMousePosition.current = { x: e.clientX, y: e.clientY };
        dragStart.current = { x: e.clientX, y: e.clientY };
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (!isDragging || !svgRef.current) return;
        
        const { width } = svgRef.current.getBoundingClientRect();
        const svgWidth = 2000; 
        const scaleFactor = svgWidth / width;

        const dx = (e.clientX - lastMousePosition.current.x) * scaleFactor;
        const dy = (e.clientY - lastMousePosition.current.y) * scaleFactor;
        
        lastMousePosition.current = { x: e.clientX, y: e.clientY };
        
        setTransform(prev => ({ 
            ...prev, 
            x: prev.x + dx / prev.k, 
            y: prev.y + dy / prev.k 
        }));
    };

    const handleMouseUp = () => {
        setIsDragging(false);
    };

    const handleClick = (t: Territory, e: React.MouseEvent | React.TouchEvent) => {
        let clientX, clientY;
        if ('changedTouches' in e) {
             clientX = e.changedTouches[0].clientX;
             clientY = e.changedTouches[0].clientY;
        } else {
             clientX = (e as React.MouseEvent).clientX;
             clientY = (e as React.MouseEvent).clientY;
        }

        const dist = Math.sqrt(
            Math.pow(clientX - dragStart.current.x, 2) + 
            Math.pow(clientY - dragStart.current.y, 2)
        );
        if (dist < 10) { // Slightly larger threshold for touch
            onTerritoryClick(t);
        }
    };

    // Touch Handlers
    const getTouchDistance = (touches: React.TouchList) => {
        return Math.sqrt(
            Math.pow(touches[0].clientX - touches[1].clientX, 2) +
            Math.pow(touches[0].clientY - touches[1].clientY, 2)
        );
    };

    const getTouchCenter = (touches: React.TouchList) => {
        return {
            x: (touches[0].clientX + touches[1].clientX) / 2,
            y: (touches[0].clientY + touches[1].clientY) / 2
        };
    };

    const handleTouchStart = (e: React.TouchEvent) => {
        if (e.touches.length === 1) {
            setIsDragging(true);
            lastMousePosition.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            dragStart.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
        } else if (e.touches.length === 2) {
            setIsDragging(false);
            lastTouchDistance.current = getTouchDistance(e.touches);
            lastTouchCenter.current = getTouchCenter(e.touches);
        }
    };

    const handleTouchMove = (e: React.TouchEvent) => {
        if (!svgRef.current) return;
        // Prevent default to stop scrolling the page while interacting with map
        // Note: React synthetic events might not support preventDefault in all cases depending on passive listeners
        // but we can try.
        
        const { width } = svgRef.current.getBoundingClientRect();
        const svgWidth = 2000;
        const scaleFactor = svgWidth / width;

        if (e.touches.length === 1 && isDragging) {
            const dx = (e.touches[0].clientX - lastMousePosition.current.x) * scaleFactor;
            const dy = (e.touches[0].clientY - lastMousePosition.current.y) * scaleFactor;
            
            lastMousePosition.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            
            setTransform(prev => ({ 
                ...prev, 
                x: prev.x + dx / prev.k, 
                y: prev.y + dy / prev.k 
            }));
        } else if (e.touches.length === 2) {
            const currentDistance = getTouchDistance(e.touches);
            const currentCenter = getTouchCenter(e.touches);

            if (lastTouchDistance.current && lastTouchCenter.current) {
                const scaleRatio = currentDistance / lastTouchDistance.current;
                const newScale = Math.min(Math.max(0.5, transform.k * scaleRatio), 10);
                
                // Calculate translation to zoom towards center
                // This is a simplified zoom-to-center logic
                // Ideally we'd adjust x/y based on the center point relative to SVG
                
                setTransform(prev => ({ ...prev, k: newScale }));
            }

            lastTouchDistance.current = currentDistance;
            lastTouchCenter.current = currentCenter;
        }
    };

    const handleTouchEnd = () => {
        setIsDragging(false);
        lastTouchDistance.current = null;
        lastTouchCenter.current = null;
    };

    return (
        <div 
            style={{ width: '100%', height: '100%', overflow: 'hidden', border: '1px solid #ccc', position: 'relative', touchAction: 'none' }}
            onWheel={handleWheel}
        >
            <div style={{ position: 'absolute', top: 10, right: 10, zIndex: 100, display: 'flex', flexDirection: 'column', gap: '5px' }}>
                <button onClick={() => setTransform(prev => ({ ...prev, k: Math.min(prev.k * 1.2, 10) }))}>+</button>
                <button onClick={() => setTransform(prev => ({ ...prev, k: Math.max(prev.k / 1.2, 0.5) }))}>-</button>
                <button onClick={() => setTransform({ x: 0, y: 0, k: 1 })}>Reset</button>
            </div>
            <svg 
                ref={svgRef}
                viewBox="0 0 2000 857" 
                style={{ width: '100%', height: '100%', cursor: isDragging ? 'grabbing' : 'grab' }}
                onMouseDown={handleMouseDown}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
            >
                <g transform={`scale(${transform.k}) translate(${transform.x}, ${transform.y})`}>
                    {territories.map((t) => (
                        <path
                            key={t.id}
                            d={t.path}
                            fill={getCountryColor(t.ownerId)}
                            stroke="black"
                            strokeWidth={0.5 / transform.k}
                            onClick={(e) => handleClick(t, e)}
                            onTouchEnd={(e) => handleClick(t, e)}
                            style={{ cursor: 'pointer', transition: 'fill 0.3s' }}
                            data-tooltip-id="my-tooltip"
                            data-tooltip-content={`${t.name} (Owner: ${t.ownerId})`}
                        />
                    ))}
                </g>
            </svg>
        </div>
    );
};
